begin;

alter table public.notification_messages
  drop constraint if exists notification_messages_day_type_check;

alter table public.notification_messages
  add constraint notification_messages_day_type_check
  check (day_type in ('daily', 'sunday', 'fasting', 'red_cross', 'black_cross'));

update public.notification_messages
set is_active = false
where language_code = 'ro'
  and country_code is null
  and calendar_code is null;

insert into public.notification_messages (
  language_code,
  country_code,
  calendar_code,
  day_type,
  theme,
  title_template,
  body_template,
  is_active
) values
  ('ro', null, null, 'daily', 'daily_001', 'Începe cu rugăciune', 'Încredințează această zi lui Dumnezeu. Rugăciunea așază pace în inimă și întărește pașii spre bine.', true),
  ('ro', null, null, 'daily', 'daily_002', 'Păstrează pacea inimii', 'Chiar și în mijlocul grijilor, caută liniștea care vine din apropierea de Dumnezeu. El nu părăsește pe cei care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_003', 'Fii recunoscător', 'Mulțumește lui Dumnezeu pentru darurile primite. Recunoștința luminează sufletul și aduce pace.', true),
  ('ro', null, null, 'daily', 'daily_004', 'Un pas spre bine', 'Fă astăzi un bine cu inimă curată. Dragostea se arată prin fapte simple și sincere.', true),
  ('ro', null, null, 'daily', 'daily_005', 'Nădejde neclintită', 'Nu lăsa descurajarea să îți stăpânească inima. Pune-ți nădejdea în Dumnezeu și mergi înainte cu răbdare.', true),
  ('ro', null, null, 'daily', 'daily_006', 'Cuvinte cu blândețe', 'Vorbește cu bunătate și răbdare. Un cuvânt rostit cu dragoste poate aduce liniște celui de lângă tine.', true),
  ('ro', null, null, 'daily', 'daily_007', 'Dumnezeu te întărește', 'În orice încercare, caută sprijinul Domnului prin rugăciune. El dă putere sufletului care se încrede în El.', true),
  ('ro', null, null, 'daily', 'daily_008', 'Lucrează cu bucurie', 'Împlinește-ți îndatoririle cu inimă curată. Orice lucru făcut cu credincioșie este o bună mărturie.', true),
  ('ro', null, null, 'daily', 'daily_009', 'Pacea începe în inimă', 'Păstrează liniștea sufletului și nu răspunde răului cu rău. Blândețea aduce rod bun.', true),
  ('ro', null, null, 'daily', 'daily_010', 'Ridică privirea', 'Când grijile devin apăsătoare, ridică-ți gândul către Dumnezeu. Rugăciunea aduce întărire și nădejde.', true),
  ('ro', null, null, 'daily', 'daily_011', 'Fii răbdător', 'Răbdarea este o lucrare a inimii. Nu te grăbi să judeci, ci păstrează pacea și bunătatea.', true),
  ('ro', null, null, 'daily', 'daily_012', 'Încredere în Domnul', 'Chiar dacă nu vezi întregul drum, mergi înainte cu credință. Dumnezeu călăuzește pașii celui smerit.', true),
  ('ro', null, null, 'daily', 'daily_013', 'Păstrează bunătatea', 'O inimă bună aduce lumină în jurul ei. Nu obosi să faci binele cu smerenie.', true),
  ('ro', null, null, 'daily', 'daily_014', 'O clipă de rugăciune', 'Oprește-te pentru câteva clipe și roagă-te. Dumnezeu ascultă inima care Îl caută cu sinceritate.', true),
  ('ro', null, null, 'daily', 'daily_015', 'Zi binecuvântată', 'Trăiește această zi cu credință, răbdare și dragoste. Fiecare început este o nouă ocazie de a face bine.', true),
  ('ro', null, null, 'daily', 'daily_016', 'Începe cu pace', 'Alege să începi această zi cu o inimă liniștită. Dumnezeu întărește pe cel care Îl caută cu credință.', true),
  ('ro', null, null, 'daily', 'daily_017', 'Păstrează nădejdea', 'Chiar și atunci când drumul pare greu, nu pierde nădejdea. Dumnezeu lucrează cu răbdare în viața fiecăruia.', true),
  ('ro', null, null, 'daily', 'daily_018', 'Iubește aproapele', 'Arată bunătate prin gesturi simple și cuvinte sincere. Dragostea apropie inimile și aduce pace.', true),
  ('ro', null, null, 'daily', 'daily_019', 'O inimă smerită', 'Smerenia deschide calea către liniștea sufletului. Dumnezeu primește rugăciunea spusă cu sinceritate.', true),
  ('ro', null, null, 'daily', 'daily_020', 'Caută liniștea', 'Lasă pentru câteva clipe grijile deoparte și ridică-ți gândul către Dumnezeu. Rugăciunea aduce odihnă inimii.', true),
  ('ro', null, null, 'daily', 'daily_021', 'Fă binele', 'Nu amâna o faptă bună atunci când o poți împlini astăzi. Bunătatea rodește în timp.', true),
  ('ro', null, null, 'daily', 'daily_022', 'Rămâi statornic', 'Credința se întărește prin răbdare și rugăciune. Continuă să mergi înainte cu încredere.', true),
  ('ro', null, null, 'daily', 'daily_023', 'Bucurie curată', 'Primește cu recunoștință binecuvântările fiecărei zile. O inimă mulțumitoare păstrează pacea.', true),
  ('ro', null, null, 'daily', 'daily_024', 'Vorbește cu blândețe', 'Cuvintele rostite cu dragoste pot aduce alinare. Alege întotdeauna bunătatea în locul asprimii.', true),
  ('ro', null, null, 'daily', 'daily_025', 'Un nou început', 'Fiecare zi este un nou prilej de a îndrepta ceea ce ai greșit și de a merge mai aproape de Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_026', 'Încredere și pace', 'Lasă neliniștea în mâinile lui Dumnezeu. El cunoaște nevoile inimii tale.', true),
  ('ro', null, null, 'daily', 'daily_027', 'Oprește-te puțin', 'Găsește câteva clipe pentru rugăciune și reculegere. Sufletul se întărește în liniște.', true),
  ('ro', null, null, 'daily', 'daily_028', 'Răspândește bunătate', 'Un gest făcut din dragoste poate aduce speranță celui aflat în nevoie. Nu obosi să faci binele.', true),
  ('ro', null, null, 'daily', 'daily_029', 'Credință vie', 'Păstrează credința în toate împrejurările. Dumnezeu rămâne aproape de cei care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_030', 'Pace și recunoștință', 'Încheie fiecare zi cu mulțumire către Dumnezeu. Recunoștința aduce liniște și întărește sufletul.', true),
  ('ro', null, null, 'daily', 'daily_031', 'Rămâi în rugăciune', 'Chiar și o rugăciune scurtă, rostită cu sinceritate, aduce liniște și întărire sufletului.', true),
  ('ro', null, null, 'daily', 'daily_032', 'Inimă plină de pace', 'Nu lăsa graba să îți tulbure sufletul. Pacea se păstrează prin credință și răbdare.', true),
  ('ro', null, null, 'daily', 'daily_033', 'Fii lumină', 'O faptă bună și un cuvânt blând pot aduce bucurie celor din jur. Dăruiește-le cu dragoste.', true),
  ('ro', null, null, 'daily', 'daily_034', 'Dumnezeu călăuzește', 'Înainte de fiecare hotărâre, caută ajutorul lui Dumnezeu. El luminează mintea și întărește inima.', true),
  ('ro', null, null, 'daily', 'daily_035', 'Mulțumește mereu', 'Recunoștința schimbă felul în care privim fiecare zi. Mulțumește lui Dumnezeu pentru toate darurile primite.', true),
  ('ro', null, null, 'daily', 'daily_036', 'Păstrează bunătatea', 'Bunătatea arătată aproapelui este o mărturie a credinței trăite cu sinceritate.', true),
  ('ro', null, null, 'daily', 'daily_037', 'Un suflet liniștit', 'Caută liniștea care vine din apropierea de Dumnezeu. Ea dă putere în orice încercare.', true),
  ('ro', null, null, 'daily', 'daily_038', 'Răbdarea rodește', 'Nu te descuraja dacă răspunsurile întârzie. Răbdarea întărește sufletul și păstrează pacea.', true),
  ('ro', null, null, 'daily', 'daily_039', 'Privește cu speranță', 'Fiecare zi aduce un nou prilej de a face bine și de a merge mai aproape de Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_040', 'Pacea lui Hristos', 'Primește cu inimă smerită pacea pe care Hristos o dă celor ce Îl caută cu credință.', true),
  ('ro', null, null, 'daily', 'daily_041', 'Iartă cu dragoste', 'Iertarea eliberează inima de povara supărării și deschide calea către pace.', true),
  ('ro', null, null, 'daily', 'daily_042', 'Cuvinte folositoare', 'Alege cuvinte care aduc încurajare și bunătate. Vorba blândă apropie inimile.', true),
  ('ro', null, null, 'daily', 'daily_043', 'Nădejde pentru fiecare zi', 'Oricât de grea ar părea calea, Dumnezeu rămâne sprijinul celor care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_044', 'Trăiește cu smerenie', 'Smerenia aduce liniște sufletului și îl ajută să primească voia lui Dumnezeu cu încredere.', true),
  ('ro', null, null, 'daily', 'daily_045', 'Pace în suflet', 'Încredințează această zi lui Dumnezeu și mergi înainte cu credință, răbdare și recunoștință.', true),
  ('ro', null, null, 'daily', 'daily_046', 'Bucură-te de fiecare zi', 'Primește fiecare zi ca pe un dar al lui Dumnezeu. Trăiește-o cu credință, bunătate și pace.', true),
  ('ro', null, null, 'daily', 'daily_047', 'O inimă recunoscătoare', 'Mulțumirea către Dumnezeu aduce liniște și întărește sufletul în toate împrejurările.', true),
  ('ro', null, null, 'daily', 'daily_048', 'Rămâi statornic', 'Nu renunța la rugăciune, chiar dacă drumul pare greu. Dumnezeu este aproape de cei care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_049', 'Începe cu bine', 'Alege să faci primul pas spre bine încă de la începutul zilei. Faptele bune aduc pace în inimă.', true),
  ('ro', null, null, 'daily', 'daily_050', 'Caută înțelepciunea', 'Roagă-L pe Dumnezeu să îți lumineze gândurile și să îți călăuzească pașii pe calea cea bună.', true),
  ('ro', null, null, 'daily', 'daily_051', 'Pacea se păstrează', 'Nu lăsa tulburarea să îți cuprindă sufletul. Rugăciunea și răbdarea aduc liniște.', true),
  ('ro', null, null, 'daily', 'daily_052', 'Dragoste prin fapte', 'Adevărata dragoste se vede în grijă, răbdare și bunătate față de aproapele.', true),
  ('ro', null, null, 'daily', 'daily_053', 'O zi cu folos', 'Fă tot ceea ce ai de împlinit cu inimă curată și cu încredere în ajutorul lui Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_054', 'Privește înainte', 'Nu rămâne prins de greșelile trecutului. Cu pocăință și nădejde poți merge înainte.', true),
  ('ro', null, null, 'daily', 'daily_055', 'Blândețea aduce pace', 'O inimă blândă răspândește liniște în familie și între cei din jur.', true),
  ('ro', null, null, 'daily', 'daily_056', 'Păstrează credința', 'Credința se întărește prin rugăciune, răbdare și încredere în purtarea de grijă a lui Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_057', 'Fă loc liniștii', 'Oprește-te pentru câteva clipe și lasă rugăciunea să îți aducă pace sufletului.', true),
  ('ro', null, null, 'daily', 'daily_058', 'Bucuria binelui', 'Bucură-te ori de câte ori poți face un bine. Dragostea arătată aproapelui nu rămâne fără rod.', true),
  ('ro', null, null, 'daily', 'daily_059', 'Rămâi aproape de Dumnezeu', 'În orice împrejurare, întoarce-ți inima către Dumnezeu. El este sprijinul celor care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_060', 'Pace și lumină', 'Fie ca această zi să fie trăită cu pace, credință și dorința sinceră de a face binele.', true),
  ('ro', null, null, 'daily', 'daily_061', 'Încredere în fiecare pas', 'Mergi înainte cu credință și lasă grijile în mâinile lui Dumnezeu. El întărește sufletul care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_062', 'Rămâi în pace', 'Nu îngădui neliniștii să îți stăpânească inima. Rugăciunea aduce liniște și nădejde.', true),
  ('ro', null, null, 'daily', 'daily_063', 'Fă bine cu bucurie', 'Orice faptă bună făcută din dragoste aduce lumină în viața ta și a celor din jur.', true),
  ('ro', null, null, 'daily', 'daily_064', 'O clipă de reculegere', 'Oprește-te pentru câteva clipe și vorbește cu Dumnezeu. El ascultă rugăciunea spusă cu sinceritate.', true),
  ('ro', null, null, 'daily', 'daily_065', 'Puterea răbdării', 'Răbdarea păstrează pacea inimii și te ajută să treci cu înțelepciune prin încercări.', true),
  ('ro', null, null, 'daily', 'daily_066', 'Inimă plină de credință', 'Credința sinceră aduce curaj și întărire. Dumnezeu nu părăsește pe cei care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_067', 'Dăruiește bunătate', 'Un gest simplu făcut cu dragoste poate schimba ziua unui om. Nu înceta să faci binele.', true),
  ('ro', null, null, 'daily', 'daily_068', 'Privește cu încredere', 'Chiar dacă nu înțelegi toate lucrurile, mergi înainte cu nădejde și rugăciune.', true),
  ('ro', null, null, 'daily', 'daily_069', 'Pacea lui Dumnezeu', 'Lasă pacea lui Dumnezeu să îți călăuzească gândurile și să îți întărească sufletul.', true),
  ('ro', null, null, 'daily', 'daily_070', 'Trăiește cu blândețe', 'Blândețea aduce liniște în familie și între oameni. Alege întotdeauna cuvântul bun.', true),
  ('ro', null, null, 'daily', 'daily_071', 'Caută binele', 'Fiecare zi oferă ocazia de a face un bine. Împlinește-o cu inimă curată.', true),
  ('ro', null, null, 'daily', 'daily_072', 'Dumnezeu este aproape', 'În orice împrejurare, ridică-ți inima către Dumnezeu. El rămâne sprijinul celor credincioși.', true),
  ('ro', null, null, 'daily', 'daily_073', 'Bucuria recunoștinței', 'Mulțumește pentru lucrurile mici și mari. Recunoștința aduce pace și întărește credința.', true),
  ('ro', null, null, 'daily', 'daily_074', 'O zi cu folos', 'Împlinește-ți datoria cu răbdare și bunătate. Lucrul făcut cu inimă curată aduce rod.', true),
  ('ro', null, null, 'daily', 'daily_075', 'Mergi cu nădejde', 'Încredințează această zi lui Dumnezeu și pășește înainte cu pace, credință și dragoste.', true),
  ('ro', null, null, 'daily', 'daily_076', 'Păstrează smerenia', 'Smerenia aduce pace sufletului și îl apropie de Dumnezeu. Mergi înainte cu inimă curată.', true),
  ('ro', null, null, 'daily', 'daily_077', 'O inimă deschisă', 'Primește fiecare om cu bunătate și respect. Dragostea sinceră aduce lumină în viața de zi cu zi.', true),
  ('ro', null, null, 'daily', 'daily_078', 'Început cu nădejde', 'Încredințează această zi lui Dumnezeu. El întărește pe cei care Îl caută cu credință.', true),
  ('ro', null, null, 'daily', 'daily_079', 'Cuvinte care zidesc', 'Alege să vorbești cu blândețe și înțelepciune. Un cuvânt bun poate aduce pace unei inimi tulburate.', true),
  ('ro', null, null, 'daily', 'daily_080', 'Răbdare în toate', 'Nu te grăbi să te mânii. Răbdarea păstrează liniștea sufletului și întărește dragostea.', true),
  ('ro', null, null, 'daily', 'daily_081', 'Bucuria credinței', 'Credința aduce curaj în încercări și pace în inimă. Rămâi aproape de Dumnezeu în fiecare zi.', true),
  ('ro', null, null, 'daily', 'daily_082', 'Fii milostiv', 'Arată înțelegere și bunătate celor din jur. Milostivirea este o lucrare frumoasă a inimii.', true),
  ('ro', null, null, 'daily', 'daily_083', 'Gând curat', 'Păstrează-ți mintea și inima îndreptate spre bine. Rugăciunea luminează gândurile.', true),
