  ('ro', null, null, 'daily', 'daily_085', 'Recunoștință zilnică', 'Mulțumește lui Dumnezeu pentru fiecare bine primit. O inimă recunoscătoare rămâne plină de nădejde.', true),
  ('ro', null, null, 'daily', 'daily_086', 'Fii sprijin', 'O vorbă bună sau un gest simplu pot aduce mângâiere aproapelui. Fă binele cu dragoste.', true),
  ('ro', null, null, 'daily', 'daily_087', 'Încredințează grijile', 'Lasă înaintea lui Dumnezeu ceea ce te apasă. Rugăciunea aduce putere și liniște.', true),
  ('ro', null, null, 'daily', 'daily_088', 'Lumina bunătății', 'Bunătatea arătată cu smerenie încălzește inimile și aduce pace între oameni.', true),
  ('ro', null, null, 'daily', 'daily_089', 'Urmează binele', 'Alege în fiecare zi ceea ce apropie sufletul de Dumnezeu. Faptele bune dau rod în timp.', true),
  ('ro', null, null, 'daily', 'daily_090', 'Pace și credință', 'Începe și încheie ziua cu rugăciune. Dumnezeu rămâne nădejdea și întărirea celor care Îl iubesc.', true),
  ('ro', null, null, 'daily', 'daily_091', 'Caută pacea', 'Păstrează pacea inimii chiar și în momentele aglomerate. Dumnezeu întărește sufletul care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_092', 'Rugăciune cu nădejde', 'Înalță o rugăciune sinceră și pune-ți încrederea în Dumnezeu. El cunoaște nevoile inimii tale.', true),
  ('ro', null, null, 'daily', 'daily_093', 'O faptă bună', 'Nu pierde prilejul de a face bine. Un gest simplu poate aduce bucurie și mângâiere.', true),
  ('ro', null, null, 'daily', 'daily_094', 'Credință statornică', 'Rămâi aproape de Dumnezeu în toate împrejurările. Credința întărește sufletul zi de zi.', true),
  ('ro', null, null, 'daily', 'daily_095', 'Blândețe și răbdare', 'Răspunde cu blândețe și păstrează răbdarea. Așa se păstrează pacea între oameni.', true),
  ('ro', null, null, 'daily', 'daily_096', 'Mulțumește lui Dumnezeu', 'Găsește în fiecare zi un motiv de mulțumire. Recunoștința aduce lumină în inimă.', true),
  ('ro', null, null, 'daily', 'daily_097', 'O inimă liniștită', 'Lasă grijile înaintea lui Dumnezeu și mergi înainte cu încredere. El este sprijinul tău.', true),
  ('ro', null, null, 'daily', 'daily_098', 'Trăiește cu bunătate', 'Bunătatea arătată aproapelui este o mărturie frumoasă a credinței trăite cu sinceritate.', true),
  ('ro', null, null, 'daily', 'daily_099', 'Început cu credință', 'Fiecare zi este un nou prilej de a merge pe calea binelui și de a rămâne aproape de Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_100', 'Pacea sufletului', 'Caută mai întâi liniștea inimii prin rugăciune. Dumnezeu aduce pace celor care Îl caută.', true),
  ('ro', null, null, 'daily', 'daily_101', 'Fii recunoscător', 'Mulțumește pentru fiecare clipă și pentru fiecare bine primit. O inimă recunoscătoare rămâne plină de pace.', true),
  ('ro', null, null, 'daily', 'daily_102', 'Rămâi aproape', 'Nu lăsa nicio zi să treacă fără un gând către Dumnezeu. Rugăciunea întărește sufletul.', true),
  ('ro', null, null, 'daily', 'daily_103', 'Lumina credinței', 'Credința luminează pașii celui care merge cu smerenie și nădejde înaintea lui Dumnezeu.', true),
  ('ro', null, null, 'daily', 'daily_104', 'Dăruiește pace', 'Fii izvor de pace prin cuvintele și faptele tale. Bunătatea aduce liniște în jur.', true),
  ('ro', null, null, 'daily', 'daily_105', 'Mergi cu Dumnezeu', 'Încredințează-I lui Dumnezeu începutul și sfârșitul acestei zile. El rămâne nădejdea celor credincioși.', true),
  ('ro', null, null, 'daily', 'daily_106', 'Rămâi cu nădejde', 'Chiar și atunci când întâmpini greutăți, păstrează-ți încrederea în Dumnezeu. El dă putere inimii care se roagă.', true),
  ('ro', null, null, 'daily', 'daily_107', 'Bucuria binelui', 'Fiecare faptă bună făcută cu smerenie aduce pace sufletului și bucurie aproapelui.', true),
  ('ro', null, null, 'daily', 'daily_108', 'O rugăciune sinceră', 'Începe această zi cu o rugăciune din inimă. Dumnezeu ascultă pe cei care Îl caută cu credință.', true),
  ('ro', null, null, 'daily', 'daily_109', 'Păstrează bunătatea', 'Nu lăsa oboseala să îți stingă bunătatea. O inimă blândă aduce lumină în jurul ei.', true),
  ('ro', null, null, 'daily', 'daily_110', 'Credință și răbdare', 'Mergi înainte fără teamă. Dumnezeu lucrează la timpul potrivit pentru binele sufletului.', true),
  ('ro', null, null, 'daily', 'daily_111', 'Pace în fiecare zi', 'Alege liniștea în locul tulburării. Rugăciunea păstrează pacea în inimă.', true),
  ('ro', null, null, 'daily', 'daily_112', 'Fii aproape', 'Fii alături de cei care au nevoie de un cuvânt bun. Dragostea se arată prin fapte simple.', true),
  ('ro', null, null, 'daily', 'daily_113', 'Încredințează totul', 'Pune înaintea lui Dumnezeu grijile și planurile tale. El călăuzește pașii celui credincios.', true),
  ('ro', null, null, 'daily', 'daily_114', 'O inimă curată', 'Păstrează-ți gândurile curate și caută binele în toate. Așa se întărește sufletul.', true),
  ('ro', null, null, 'daily', 'daily_115', 'Trăiește cu blândețe', 'Blândețea aduce pace în familie și între oameni. Fii răbdător și înțelegător.', true),
  ('ro', null, null, 'daily', 'daily_116', 'Recunoștință și pace', 'Mulțumește lui Dumnezeu pentru fiecare început și pentru fiecare bine primit cu dragoste.', true),
